  /*--trigger-hover-icon-color: #fff;*/

  /* main */
  --main-height: calc(100% - var(--footer-height));
  --main-width: 100%;

  /* footer */
  --footer-height: 60px;
  --footer-width: 100%;

  /* layout end */

}

